<div class="container">

  <!-- Header -->
  <div class="header">
    <div class="header-badges">
      <div class="badge-left">必过！</div>
      <div></div>
      <div class="badge-right">工具在手<br>管理不愁！</div>
    </div>
    <h1><span class="highlight">软考高项</span> 各子过程可用工具与技术大全</h1>
    <div class="subtitle">依据：《信息系统项目管理师教程（第4版）》</div>
  </div>

  <!-- Row 1: Sections 1, 2, 3 -->
  <div class="grid-3">
    <!-- Section 1: 整体管理 -->
    <div class="section-card">
      <div class="section-header bg-blue">
        <span>1. 整体管理</span>
        <span class="icon">📋</span>
      </div>
      <table>
        <tr><th>子过程</th><th>工具与技术</th></tr>
        <tr><td>1.1 制定项目章程</td><td>专家判断、引导技术、会议</td></tr>
        <tr><td>1.2 制定项目管理计划</td><td>专家判断、引导技术、会议</td></tr>
        <tr><td>1.3 指导与管理项目工作</td><td>项目管理信息系统、会议</td></tr>
        <tr><td>1.4 管理项目知识</td><td>知识管理、信息管理</td></tr>
        <tr><td>1.5 监控项目工作</td><td>数据分析、决策、会议</td></tr>
        <tr><td>1.6 实施整体变更控制</td><td>变更控制工具、决策、数据分析</td></tr>
        <tr><td>1.7 结束项目或阶段</td><td>专家判断、数据分析、会议</td></tr>
      </table>
    </div>

    <!-- Section 2: 范围管理 -->
    <div class="section-card">
      <div class="section-header bg-green">
        <span>2. 范围管理</span>
        <span class="icon">📐</span>
      </div>
      <table>
        <tr><th>子过程</th><th>工具与技术</th></tr>
        <tr><td>2.1 规划范围管理</td><td>专家判断、会议、数据分析</td></tr>
        <tr><td>2.2 收集需求</td><td>访谈、焦点小组、引导式研讨会、群体创新/决策技术、问卷、原型法、标杆对照、系统交互图、文件分析</td></tr>
        <tr><td>2.3 定义范围</td><td>产品分析、备选方案生成、引导式研讨会</td></tr>
        <tr><td>2.4 创建WBS</td><td>分解、专家判断</td></tr>
        <tr><td>2.5 确认范围</td><td>检查、群体决策技术</td></tr>
        <tr><td>2.6 控制范围</td><td>偏差分析</td></tr>
      </table>
    </div>

    <!-- Section 3: 进度管理 -->
    <div class="section-card">
      <div class="section-header bg-orange">
        <span>3. 进度管理</span>
        <span class="icon">🕐</span>
      </div>
      <table>
        <tr><th>子过程</th><th>工具与技术</th></tr>
        <tr><td>3.1 规划进度管理</td><td>专家判断、数据分析、会议</td></tr>
        <tr><td>3.2 定义活动</td><td>分解、滚动式规划、专家判断</td></tr>
        <tr><td>3.3 排列活动顺序</td><td>紧前关系绘图法（PDM）、确定和整合依赖关系、提前量和滞后量</td></tr>
        <tr><td>3.4 估算活动持续时间</td><td>类比估算、参数估算、三点估算、自下而上估算、储备分析</td></tr>
        <tr><td>3.5 制定进度计划</td><td>关键路径法（CPM）、资源优化、进度压缩、蒙特卡洛模拟</td></tr>
        <tr><td>3.6 控制进度</td><td>数据分析（挣值分析、迭代燃尽图、绩效审查）、进度压缩、资源优化</td></tr>
      </table>
    </div>
  </div>

  <!-- Row 2: Sections 4, 5, 6 -->
  <div class="grid-3">
    <!-- Section 4: 成本管理 -->
    <div class="section-card">
      <div class="section-header bg-purple">
        <span>4. 成本管理</span>
        <span class="icon">💰</span>
      </div>
      <table>
        <tr><th>子过程</th><th>工具与技术</th></tr>
        <tr><td>4.1 规划成本管理</td><td>专家判断、数据分析</td></tr>
        <tr><td>4.2 估算成本</td><td>类比估算、参数估算、自下而上估算、三点估算、储备分析、质量成本</td></tr>
        <tr><td>4.3 制定预算</td><td>成本汇总、储备分析、历史关系</td></tr>
        <tr><td>4.4 控制成本</td><td>挣值分析（EV/PV/AC）、偏差分析、趋势分析、储备分析</td></tr>
      </table>
    </div>

    <!-- Section 5: 质量管理 -->
    <div class="section-card">
      <div class="section-header bg-pink">
        <span>5. 质量管理</span>
        <span class="icon"></span>
      </div>
      <table>
        <tr><th>子过程</th><th>工具与技术</th></tr>
        <tr><td>5.1 规划质量管理</td><td>标杆对照、成本效益分析、质量成本</td></tr>
        <tr><td>5.2 管理质量</td><td>老七种工具（因果图/鱼骨图、流程图、直方图、帕累托图、控制图、散点图、核查表）、质量审计、过程分析、根本原因分析</td></tr>
        <tr><td>5.3 控制质量</td><td>老七种工具、统计抽样、检查、测试/产品评估</td></tr>
      </table>
    </div>

    <!-- Section 6: 资源管理 -->
    <div class="section-card">
      <div class="section-header bg-teal">
        <span>6. 资源管理</span>
        <span class="icon">👥</span>
      </div>
      <table>
        <tr><th>子过程</th><th>工具与技术</th></tr>
        <tr><td>6.1 规划资源管理</td><td>数据表现（责任分配矩阵RAM/组织分解结构OBS）、组织理论</td></tr>
        <tr><td>6.2 估算活动资源</td><td>自下而上估算、类比估算、参数估算、备选方案分析</td></tr>
        <tr><td>6.3 获取资源</td><td>预分配、谈判、虚拟团队</td></tr>
        <tr><td>6.4 建设团队</td><td>人际关系与团队技能（冲突管理、情商、影响力、领导力）、基本规则、培训、团队建设活动</td></tr>
        <tr><td>6.5 管理团队</td><td>冲突管理、情商、影响、领导力、观察/交谈、绩效评估</td></tr>
        <tr><td>6.6 控制资源</td><td>数据分析（绩效审查）</td></tr>
      </table>
    </div>
  </div>

  <!-- Row 3: Sections 7, 8, 9 -->
  <div class="grid-3">
    <!-- Section 7: 沟通管理 -->
    <div class="section-card">
      <div class="section-header bg-yellow">
        <span>7. 沟通管理</span>
        <span class="icon">📢</span>
      </div>
      <table>
        <tr><th>子过程</th><th>工具与技术</th></tr>
        <tr><td>7.1 规划沟通管理</td><td>沟通需求分析、沟通技术、沟通模型</td></tr>
        <tr><td>7.2 管理沟通</td><td>沟通方法（推式/拉式/交互式沟通）、人际关系与团队技能、演示、项目报告</td></tr>
        <tr><td>7.3 监督沟通</td><td>干系人参与度评估矩阵、数据分析</td></tr>
      </table>
      <div class="comm-methods">
        <h4>沟通方法三大类：</h4>
        <p>✈️ <b>推式沟通：</b>发送方主动推送信息<br>
        📥 <b>拉式沟通：</b>接收方自行获取信息<br>
        🔄 <b>交互式沟通：</b>双方多向交流</p>
      </div>
    </div>

    <!-- Section 8: 风险管理 -->
    <div class="section-card">
      <div class="section-header bg-red">
        <span>8. 风险管理</span>
        <span class="icon">⚠️</span>
      </div>
      <table>
        <tr><th>子过程</th><th>工具与技术</th></tr>
        <tr><td>8.1 规划风险管理</td><td>专家判断、数据分析、会议</td></tr>
        <tr><td>8.2 识别风险</td><td>头脑风暴、德尔菲技术、根本原因分析、核对单、假设分析、SWOT分析、系统或过程流程图、因果图/鱼骨图、文件审查、专家判断</td></tr>
        <tr><td>8.3 实施定性风险分析</td><td>风险概率与影响评估、概率与影响矩阵、风险分类、数据质量评估、风险紧迫性评估、专家判断</td></tr>
        <tr><td>8.4 实施定量风险分析</td><td>模拟/蒙特卡洛分析、敏感性分析（龙卷风图）、决策树分析、影响图</td></tr>
        <tr><td>8.5 规划风险应对</td><td>威胁应对策略（上报、规避、转移、减轻、接受）、机会应对策略（上报、开拓、分享、提高、接受）</td></tr>
        <tr><td>8.6 实施风险应对</td><td>专家判断、人际关系与团队技能、项目管理信息系统</td></tr>
        <tr><td>8.7 监督风险</td><td>风险审计、技术绩效分析、储备分析、会议</td></tr>
      </table>
      <div class="risk-summary">
        <h4>⭐ 识别风险常用清单：7种分析工具 + 6种数据收集方法 + 图解技术</h4>
        <p><b>分析工具：</b>专家判断、根本原因分析、假设分析、SWOT分析、流程图等<br>
        <b>数据收集：</b>头脑风暴、德尔菲技术、核对单、文件审查、访谈、问卷等<br>
        <b>图解技术：</b>因果图/鱼骨图、系统或过程流程图等</p>
      </div>
    </div>

    <!-- Section 9: 采购管理 -->
    <div class="section-card">
      <div class="section-header bg-navy">
        <span>9. 采购管理</span>
        <span class="icon">🛒</span>
      </div>
      <table>
        <tr><th>子过程</th><th>工具与技术</th></tr>
